import numpy as np
from PIL import Image
im = Image.open('images/fig_093.png').convert('RGB')
a = np.array(im).astype(int)
H,W,_ = a.shape
r,g,b = a[:,:,0],a[:,:,1],a[:,:,2]
black = (r<130)&(g<130)&(b<130)

# 1) white pockets enclosed by black: flood fill from border over ~black
from collections import deque
notblack = ~black
seen = np.zeros((H,W), bool)
q = deque()
for i in range(H):
    for j in (0, W-1):
        if notblack[i,j] and not seen[i,j]: seen[i,j]=True; q.append((i,j))
for j in range(W):
    for i in (0, H-1):
        if notblack[i,j] and not seen[i,j]: seen[i,j]=True; q.append((i,j))
while q:
    y,x = q.popleft()
    for dy in (-1,0,1):
        for dx in (-1,0,1):
            ny,nx = y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and notblack[ny,nx] and not seen[ny,nx]:
                seen[ny,nx]=True; q.append((ny,nx))
pocket = notblack & ~seen
ys,xs = np.where(pocket)
print(\"white pockets (size>=3):\")
# cluster pockets
from scipy import ndimage
lab, n = ndimage.label(pocket)
for k in range(1, n+1):
    m = lab==k
    s = m.sum()
    if s >= 2:
        yy,xx = np.where(m)
        print(f\"  center=({xx.mean():7.2f},{yy.mean():7.2f}) size={s}\")
